-- ============================================================================\n-- Migration: Rule 2202 Methodology Registry Seed Data\n-- Canonical AVR, VMT, ERT, and VTEC methodologies for the public (platform) institution.\n-- ============================================================================\n-- This seed is intended to run once after 202609020002_rule2202_domain_model.sql\n-- has been applied. It populates the rule2202_methodologies table with the four\n-- canonical methodology families every Rule 2202 calculation should reference.\n--\n-- Institution scoping:\n--   - Platform-level (public institution) methodologies are seeded with\n--     institution_id = '00000000-0000-0000-0000-000000000000'.\n--   - Institution-specific methodologies (e.g., a custom AVR survey instrument)\n--     would be seeded with that institution's id.\n--   - Adjust the institution_id values to match your Supabase project's\n--     actual institution rows before running.\n-- ============================================================================\n\n-- ---------------------------------------------------------------------------\n-- Public institution placeholder (if it does not already exist in your project)\n-- ---------------------------------------------------------------------------\n-- If your project already has a public/platform institution row, replace the\n-- id below with that row's id and delete this INSERT.\ninsert into public.institutions (id, name, status, created_at, updated_at)\nvalues\n  ('00000000-0000-0000-0000-000000000000', 'Platform (public)', 'active', now(), now())\non conflict (id) do nothing;\n\n-- ---------------------------------------------------------------------------\n-- AVR survey methodology (the baseline survey-based Average Vehicle Ridership)\n-- ---------------------------------------------------------------------------\ninsert into public.rule2202_methodologies (\n  id, institution_id, methodology_name, methodology_type, metric_type,\n  applicable_pollutants, factor_year, source_name, source_url,\n  source_publication_date, formula_text, result_units, assumptions,\n  is_active, version, created_at, updated_at\n) values (\n  '00000000-0000-0000-0000-000000000001',\n  '00000000-0000-0000-0000-000000000000',\n  'AQMD Rule 2202 AVR survey — baseline',\n  'avr_survey',\n  'avr',\n  ARRAY['co', 'nmvoc', 'rnx', 'pm10', 'pm2_5', 'ntox'],\n  2026,\n  'SCAQMD Rule 2202 text (Revised 2024)',\n  'https://www.aqmd.gov/docs/default-source/regulations/rules-schemas/rule-2202---employer-based-commuter-choice-program.pdf',\n  '2024-07-01',\n  'AVR = sum(weighted_vehicle_trips) / report_period_average_employees\n\nwhere:\n  weighted_vehicle_trips = sum over commuter records of:\n    - drive_alone, motorcycle, bus_pool, cww_day_off                    : 1.0 trip\n    - carpool, shared_motorcycle                                        : 1 / vehicle_occupancy trips\n    - vanpool                                                           : 1 / vehicle_occupancy trips (capped)\n    - telecommute, cww_day_off                                          : 0 trips\n    - transit, bicycle, walk, zev, non_commuting, not_specified        : not counted as vehicle trips\n\nreport_period_average_employees = mean of 6 monthly employee counts\n  (employee_count_month_1 through employee_count_month_6),\n  ignoring null months; returns NULL if no months are reported.',\n  'avr (dimensionless ratio)',\n  ARRAY['Survey responses reflect a representative workweek',\n        'Vehicle occupancy is self-reported and verified by ETC where possible',\n        'Monthly employee counts are from HR/payroll records',\n        'Survey period is 6 months aligned to the employer reporting year'],\n  true,\n  '1.0.0',\n  now(),\n  now()\n);\n\n-- ---------------------------------------------------------------------------\n-- VMT estimation methodology (vehicle-miles traveled reduction estimate)\n-- ---------------------------------------------------------------------------\ninsert into public.rule2202_methodologies (\n  id, institution_id, methodology_name, methodology_type, metric_type,\n  applicable_pollutants, factor_year, source_name, source_url,\n  source_publication_date, formula_text, result_units, assumptions,\n  is_active, version, created_at, updated_at\n) values (\n  '00000000-0000-0000-0000-000000000002',\n  '00000000-0000-0000-0000-000000000000',\n  'AQMD Rule 2202 VMT estimation — baseline',\n  'vmt_estimation',\n  'vmt',\n  ARRAY['co', 'nmvoc', 'rnx', 'pm10', 'pm2_5', 'ntox'],\n  2026,\n  'SCAQMD Rule 2202 text + EMFAC2024 emission factors',\n  'https://www.aqmd.gov/docs/default-source/regulations/rules-schemas/rule-2202---employer-based-commuter-choice-program.pdf',\n  '2024-07-01',\n  'annual_vmt_reduced = sum over commuter records of:\n  (one_way_distance_miles * 2 trips/day * work_days_per_year * vmt_reduction_factor)\n\nwhere:\n  work_days_per_year = 260 - (telecommute_days_per_week * 52)   (default 260 if telecommute unknown)\n  vmt_reduction_factor depends on commute mode:\n    - drive_alone, motorcycle, bus_pool, cww_day_off             : 0.0  (no reduction credited)\n    - carpool                                                  : (1 - 1/vehicle_occupancy)\n    - vanpool                                                  : (1 - 1/vehicle_occupancy)\n    - shared_motorcycle                                        : (1 - 1/vehicle_occupancy)\n    - telecommute, cww_day_off                                 : 1.0  (full VMT reduction for non-commute days)\n    - transit, bicycle, walk, zev, non_commuting, not_specified : 0.0  (no VMT reduction credited under baseline VMT method)\n\nannual_vmt_baseline (for comparison) = sum of (one_way_distance_miles * 2 * 260)\n  over the same commuter records, assuming all trips were drive_alone.\n\nannual_vmt_reduction = annual_vmt_baseline - annual_vmt_reduced.\n\nVMT reduction is a planning estimate, not a metered measurement.',\n  'annual_vmt_reduced (vehicle-miles/year)',\n  ARRAY['One-way distance is self-reported or zip-to-zip estimated; not GPS-metered',\n        'Workdays per year assume a 5-day workweek; adjust per employer schedule',\n        'VMT reduction is a conservative estimate; actual peak-period VMT may differ'],\n  true,\n  '1.0.0',\n  now(),\n  now()\n);\n\n-- ---------------------------------------------------------------------------\n-- ERT per pollutant (Emission Reduction Target) methodology\n-- ---------------------------------------------------------------------------\ninsert into public.rule2202_methodologies (\n  id, institution_id, methodology_name, methodology_type, metric_type,\n  applicable_pollutants, factor_year, source_name, source_url,\n  source_publication_date, formula_text, result_units, assumptions,\n  is_active, version, created_at, updated_at\n) values (\n  '00000000-0000-0000-0000-000000000003',\n  '00000000-0000-0000-0000-000000000000',\n  'AQMD Rule 2202 ERT per pollutant — baseline (EMFAC2024 factors)',\n  'ert_per_pollutant',\n  'ert',\n  ARRAY['co', 'nmvoc', 'rnx', 'pm10', 'pm2_5', 'ntox'],\n  2026,\n  'SCAQMD Rule 2202 text + EMFAC2024 (california air resources board emission factors, 2024 model year)',\n  'https://www.arb.ca.gov/emfac/emfac2024/emfac2024.htm',\n  '2024-01-01',\n  'ert_pollutant = annual_vmt_reduced * emission_factor_pollutant\n\nwhere:\n  annual_vmt_reduced = VMT estimation result (annual_vmt_reduced, in vehicle-miles/year)\n  emission_factor_pollutant = EMFAC2024 emission factor for the given pollutant,\n    in units of pollutant/kg or lb per vehicle-mile, for the representative\n    vehicle fleet mix (light-duty gasoline fleet, default assumption).\n\nThe ERT is the tons (or lbs) per year of each pollutant reduced by the VMT\nreduction, using EMFAC2024 emission factors as the source of truth.\n\nFor Rule 2202 compliance, each pollutant has its own ERT target set by AQMD.\nThe employer must achieve ERT_co, ERT_nmvoc, ERT_rnx, ERT_pm10,\nERT_pm2_5, and ERT_ntox, and the methodology must document which emission\nfactor year and source were used.',\n  'lbs/year per pollutant (or tons/year as configured)',\n  ARRAY['EMFAC2024 factors are annual averages for the region fleet mix',\n        'Emission factors assume light-duty gasoline vehicles unless employer fleet mix differs',\n        'ERT is calculated on the VMT reduction, which is itself an estimate,\n         so ERT carries the same uncertainty as the VMT estimate',\n        'If the employer fleet mix is materially different from the default,\n         the methodology must be updated with a fleet-specific factor'],\n  true,\n  '1.0.0',\n  now(),\n  now()\n);\n\n-- ---------------------------------------------------------------------------\n-- VTEC calculation methodology (Voluntary TDM Employer Credit)\n-- ---------------------------------------------------------------------------\ninsert into public.rule2202_methodologies (\n  id, institution_id, methodology_name, methodology_type, metric_type,\n  applicable_pollutants, factor_year, source_name, source_url,\n  source_publication_date, formula_text, result_units, assumptions,\n  is_active, version, created_at, updated_at\n) values (\n  '00000000-0000-0000-0000-000000000004',\n  '00000000-0000-0000-0000-000000000000',\n  'AQMD Rule 2202 VTEC calculation — baseline (peak and off-peak)',\n  'vtec_calculation',\n  'vtec',\n  ARRAY['co', 'nmvoc', 'rnx', 'pm10', 'pm2_5', 'ntox'],\n  2026,\n  'SCAQMD Rule 2202 text (employer-based commuter choice program) + EMFAC2024 factors',\n  'https://www.aqmd.gov/docs/default-source/regulations/rules-schemas/rule-2202---employer-based-commuter-choice-program.pdf',\n  '2024-07-01',\n  'vtec = (baseline_emissions - program_emissions) * credit_factor\n\nwhere:\n  baseline_emissions = emissions that would occur if all employees drove alone\n    (drive_alone vehicle trips * one-way distance * 2 trips/day * work days/year\n     * EMFAC2024 emission factor for each pollutant)\n  program_emissions = emissions actually occurring under the employer program,\n    using weighted vehicle trips (AVR weighting) and EMFAC2024 factors\n  credit_factor = Rule 2202-defined credit multiplier applied to the net\n    emissions reduction. The credit factor may differ for peak vs off-peak\n    hours, for different pollutant categories, and for different employer\n    program elements (e.g., telework credit, vanpool credit, EV infrastructure\n    credit).\n\nVTEC calculation requires:\n  - AVR (to determine weighted vehicle trips)\n  - VMT reduction estimate (to determine program_emissions)\n  - ERT per pollutant (to compare against AQMD targets)\n  - Peak vs off-peak segmentation if the employer has separate peak/off-peak\n    programs or the Rule 2202 credit structure distinguishes them.\n\nVTEC result is the credits earned, in units defined by the methodology\n(typically 'credits' or 'lbs/year reduced'), and must be documented with\nthe factor year, emission factor source, and credit_factor value used.',\n  'credits / lbs-per-year-reduced (per methodology configuration)',\n  ARRAY['VTEC depends on AVR and VMT results, which are themselves estimates',\n        'Peak/off-peak segmentation requires arrival/departure window data from commuter surveys',\n        'Credit_factor values are defined by Rule 2202 and may change with rule revisions',\n        'EMFAC2024 factors are the source of truth for emission rates'],\n  true,\n  '1.0.0',\n  now(),\n  now()\n);\n\n-- ---------------------------------------------------------------------------\n-- Verification note\n-- ---------------------------------------------------------------------------\n-- After seeding, verify the records:\n--\n--   select id, methodology_name, methodology_type, metric_type,\n--          factor_year, source_name, source_url, is_active, version\n--   from public.rule2202_methodologies\n--   where institution_id = '00000000-0000-0000-0000-000000000000'\n--   order by metric_type, factor_year, created_at desc;\n--\n-- Expected: 4 rows (AVR survey, VMT estimation, ERT per pollutant, VTEC calculation).\n--\n-- Each institution may add its own methodology records (e.g., a custom AVR survey\n-- instrument approved by AQMD). Institution-specific records use that institution's\n-- id in institution_id, and are visible only to users affiliated with that\n-- institution (per the RLS SELECT policy).\n